import os, json
from bioblend.galaxy import GalaxyInstance
gi=GalaxyInstance(os.environ['GALAXY_URL'], key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip())
for q in ['blastn','ncbi_blastn_wrapper','NCBI BLAST+ blastn']:
    print('QUERY', q)
    try:
        ids=gi.tools.get_tools(name=q)
        print(ids[:5])
    except Exception as e: print(e)
# search api strings
for tid in gi.tools.get_tools(tool_id='blastn')[:20]: print(tid)
PY"

